local Connection = require(script.Parent.Connection)
local Player = game:GetService("Players").LocalPlayer
if not Player then
    error("Player not found")
end
local PlayerGui = Player:WaitForChild("PlayerGui")
local _gui = nil
local module = {}
local Guidance = require(script.Guidance)
local _guidances = {}
local _guideIndex = 0
local _starting = false

local _current = nil
local SCREENSIZE = Vector2.new(game.Workspace.CurrentCamera.ViewportSize.X, game.Workspace.CurrentCamera.ViewportSize.Y)
local THICKNESS = 10

if SCREENSIZE.Y > 1080 then
    THICKNESS = 10
elseif SCREENSIZE.Y > 720 then
    THICKNESS = 7
elseif SCREENSIZE.Y > 480 then
    THICKNESS = 5
else
    THICKNESS = 3
end

local _triggerevent = Instance.new("BindableEvent")
module.Triggerred = _triggerevent.Event
local _showevent = Instance.new("BindableEvent")
module.Shown = _showevent.Event

local function _createGui()
    _gui = Instance.new("ScreenGui")
    _gui.Name = "__NezaOnboardingGui"
    _gui.DisplayOrder = 10^6
    _gui.ResetOnSpawn = false
    _gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    _gui.IgnoreGuiInset = false
    _gui.Parent = PlayerGui
    _gui.ClipToDeviceSafeArea = false
    _gui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    _gui.Enabled = false
    
    local blockBtn = Instance.new("TextButton", _gui)
    blockBtn.Name = "BlockBtn"
    blockBtn.Size = UDim2.new(1, 0, 1, 0)
    blockBtn.BackgroundTransparency = 1
    blockBtn.Active = false
    blockBtn.ZIndex = 0
    blockBtn.Text = ""

    return _gui
end

local function getGui()
    if not _gui then
        _gui = _createGui()
    end
    return _gui
end

local function _createFocusFrame()
    local gui = getGui()
    local focus = Instance.new("Frame", gui)
    focus.Name = "Focus"
    focus.Size = UDim2.new(1, 0, 1, 0)
    focus.BackgroundTransparency = 1
    focus.Position = UDim2.new(.5, 0, .5, 0)
    focus.AnchorPoint = Vector2.new(.5, .5)
    focus.ZIndex = 10
    -- focus.Active = true

    local uiscale = Instance.new("UIScale", focus)
    uiscale.Scale = 1

    local uistroke = Instance.new("UIStroke", focus)
    uistroke.Thickness = THICKNESS
    uistroke.Color = Color3.fromRGB(255, 213, 60)
    uistroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

    local frame1 = Instance.new("Frame", focus)
    frame1.Size = UDim2.fromOffset(SCREENSIZE.X * 2, SCREENSIZE.Y * 2)
    frame1.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    frame1.BackgroundTransparency = .5
    frame1.AnchorPoint = Vector2.new(0, 1)
    frame1.Position = UDim2.new(0, 0, 0, 0)
    frame1.BorderSizePixel = 0
    frame1.Active = true
    frame1.Name = "__Frame1"
    frame1.ZIndex = 0

    local frame2 = Instance.new("Frame", focus)
    frame2.Size = UDim2.fromOffset(SCREENSIZE.X * 2, SCREENSIZE.Y * 2)
    frame2.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    frame2.BackgroundTransparency = .5
    frame2.AnchorPoint = Vector2.new(0, 0)
    frame2.Position = UDim2.new(1, 0, 0, 0)
    frame2.BorderSizePixel = 0
    frame2.Active = true
    frame2.Name = "__Frame2"
    frame2.ZIndex = 0

    local frame3 = Instance.new("Frame", focus)
    frame3.Size = UDim2.fromOffset(SCREENSIZE.X * 2, SCREENSIZE.Y * 2)
    frame3.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    frame3.BackgroundTransparency = .5
    frame3.AnchorPoint = Vector2.new(1, 0)
    frame3.Position = UDim2.new(1, 0, 1, 0)
    frame3.BorderSizePixel = 0
    frame3.Active = true
    frame3.Name = "__Frame3"
    frame3.ZIndex = 0

    local frame4 = Instance.new("Frame", focus)
    frame4.Size = UDim2.fromOffset(SCREENSIZE.X * 2, SCREENSIZE.Y * 2)
    frame4.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    frame4.BackgroundTransparency = .5
    frame4.AnchorPoint = Vector2.new(1, 1)
    frame4.Position = UDim2.new(0, 0, 1, 0)
    frame4.BorderSizePixel = 0
    frame4.Active = true
    frame4.Name = "__Frame4"
    frame4.ZIndex = 0

    return focus
end

function module:Show(idx)
    _guideIndex = idx or 1
    local guidance
    for i, v in pairs(_guidances) do
        if i == idx then
            guidance = v
            break
        end
    end
    if _current and _current ~= guidance then
        module:Clean()
    end

    local gui = getGui()
    gui.Enabled = true
    local focus = gui:FindFirstChild("Focus") or _createFocusFrame()
    _current = guidance
    guidance:Show(focus)
    _showevent:Fire(guidance, idx)
end

function module:Get()
    return _guidances
end

function module:GetCount()
    local count = 0
    for _, guidance in pairs(_guidances) do
        count = count + 1
    end
    return count
end

function module:Stop()
    _starting = false
    module:Clean()
    Connection.SetSourceConnectionsEnabled(true)
end

function module:Start(idx)
    _starting = true
    Connection.SetSourceConnectionsEnabled(false)
end

function module:Clean()
    local gui = getGui()
    local focus = gui:FindFirstChild("Focus") or _createFocusFrame()
    focus:Destroy()
    gui.Enabled = false
    _current = nil
end

function module:Add(connection, order, config)
    local guidance = Guidance.new(connection, config)
    if not order then
        table.insert(_guidances, guidance)
        for i, v in pairs(_guidances) do
            if guidance == v then
                order = i
                break
            end
        end
    else
        _guidances[order] = guidance
    end

    local gui = getGui()
    guidance.Triggerred:Connect(function()
    print(_guidances)
    gui.Enabled = true
        local focus = gui:FindFirstChild("Focus") or _createFocusFrame()
        _triggerevent:Fire(guidance)
        if module:GetCount() > 0 and _starting then
            local nextGuidance = nil
            for i, guidance in pairs(_guidances) do
                if i >= _guideIndex + 1 then
                    nextGuidance = guidance
                    _guideIndex = i
                    break
                end
            end
            if nextGuidance then
                _current = nextGuidance
                _current:Show(focus)
                _showevent:Fire(guidance, order)
            else
                module:Clean()
            end
        else
            module:Clean()
        end
    end)

    local currentIndex = _guideIndex
    if order > currentIndex and _starting then
        module:Show(order)
    end
end

return module